/* portrait-photo.js
 * The portrait, kept as data inside a script so that a canvas can read
 * it back even when the page is opened straight from disk.
 */
(function (root) {
  'use strict';
  var LJ = (root.LJ = root.LJ || {});
  LJ.portraitPhoto = { w: 800, h: 1000, src: 'data:image/jpeg;base64,' };
})(window);
